func (this *Zebpay) ParseBalance(response any) any {
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": nil,
		"datetime":  nil,
	}
	var currencyList any = this.SafeList(response, "data", []any{})
	for i := 0; IsLessThan(i, GetArrayLength(currencyList)); i++ {
		var entry any = GetValue(currencyList, i)
		var account any = this.Account()
		AddElementToObject(account, "total", this.SafeString(entry, "total"))
		AddElementToObject(account, "free", this.SafeString(entry, "free"))
		AddElementToObject(account, "used", this.SafeString(entry, "used"))
		var currencyId any = this.SafeString(entry, "currency")
		var code any = this.SafeCurrencyCode(currencyId)
		if IsTrue(!IsEqual(code, nil)) {
			AddElementToObject(result, code, account)
		}
	}
	return this.SafeBalance(result)
}
func (this *Zebpay) ParsePosition(position any, optionalArgs ...any) any {
	//
	// isolated
	//    {
	//        "id":"long",
	//        "symbol":"pf_ftmusd",
	//        "entryPrice":"0.4921",
	//        "datetime":"2023-02-22T11:37:16.685Z",
	//        "contractSize":"1",
	//        "leverage":"1.0"
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var leverage any = this.SafeNumber(position, "leverage")
	var datetime any = this.SafeString(position, "datetime")
	var marketId any = this.SafeString(position, "symbol")
	market = this.SafeMarket(marketId, market)
	return map[string]any{
		"info":                        position,
		"symbol":                      marketId,
		"timestamp":                   this.Parse8601(datetime),
		"datetime":                    datetime,
		"initialMargin":               this.SafeNumber(position, "initialMargin"),
		"initialMarginPercentage":     nil,
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"entryPrice":                  this.SafeNumber(position, "entryPrice"),
		"notional":                    this.SafeNumber(position, "notional"),
		"leverage":                    leverage,
		"unrealizedPnl":               nil,
		"contracts":                   this.SafeNumber(position, "contracts"),
		"contractSize":                this.SafeNumber(market, "contractSize"),
		"marginRatio":                 nil,
		"liquidationPrice":            this.SafeNumber(position, "liquidationPrice"),
		"markPrice":                   nil,
		"collateral":                  nil,
		"marginType":                  "isolated",
		"side":                        this.SafeString(position, "side"),
		"percentage":                  nil,
	}
}
