func (this *Zebpay) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	//     [
	//        {
	//            "symbol": "BTC-INR",
	//            "bestBid": "4900000",
	//            "bestBidQty": "0.00014938",
	//            "bestAsk": "",
	//            "bestAskQty": "0",
	//            "priceChange": "-98134.56",
	//            "priceChangePercent": "-1.84",
	//            "high": "5433400",
	//            "low": "5333400",
	//            "vol": "0.0002",
	//            "volValue": "1066.68",
	//            "last": "5333400"
	//        }
	//     ]
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.SafeInteger2(ticker, "timestamp", "ts")
	var marketId any = this.SafeString(ticker, "symbol")
	market = this.SafeMarket(marketId)
	var close any = this.SafeString(ticker, "close")
	var last any = this.SafeString(ticker, "last")
	var percentage any = this.SafeString(ticker, "percentage")
	var bidVolume any = this.SafeString(ticker, "bidVolume")
	var askVolume any = this.SafeString(ticker, "askVolume")
	return this.SafeTicker(map[string]any{
		"id":            marketId,
		"symbol":        GetValue(market, "symbol"),
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     bidVolume,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     askVolume,
		"vwap":          nil,
		"open":          nil,
		"close":         close,
		"last":          last,
		"previousClose": this.SafeString(ticker, "previousClose"),
		"change":        this.SafeString(ticker, "change"),
		"percentage":    percentage,
		"average":       this.SafeString(ticker, "average"),
		"baseVolume":    this.SafeString(ticker, "baseVolume"),
		"quoteVolume":   this.SafeString(ticker, "quoteVolume"),
		"markPrice":     nil,
		"info":          ticker,
	}, market)
}
func (this *Zebpay) ParseMarginModification(info any, optionalArgs ...any) any {
	//
	//    {
	//         "symbol": "BTCINR",
	//         "type": "reduce",
	//         "amount": 1000,
	//         "code": "INR",
	//         "status": "ok"
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp int64 = this.Milliseconds()
	return map[string]any{
		"info":       info,
		"symbol":     this.SafeString(market, "id"),
		"type":       nil,
		"marginMode": nil,
		"amount":     this.SafeNumber(info, "amount"),
		"total":      nil,
		"code":       this.SafeString(info, "code"),
		"status":     this.SafeString(info, "status"),
		"timestamp":  timestamp,
		"datetime":   this.Iso8601(timestamp),
	}
}
func (this *Zebpay) Sign(path any, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	method := GetArg(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	params = this.Omit(params, "defaultType")
	var isV1 bool = IsGreaterThan(GetIndexOf(path, "v1/"), OpNeg(1))
	var marketType any = Ternary(IsTrue(isV1), "swap", "spot")
	var url any = GetValue(GetValue(this.Urls, "api"), marketType)
	var tail any = Add("/api/", this.ImplodeParams(path, params))
	url = Add(url, tail)
	var timestamp string = ToString(this.Milliseconds())
	var signature string = ""
	var query any = this.Omit(params, this.ExtractParams(path))
	var queryLength int = GetArrayLength(ObjectKeys(query))
	var access any = this.SafeString(api, 0, "public")
	if IsTrue(IsEqual(access, "public")) {
		if IsTrue(IsTrue(IsEqual(method, "GET")) || IsTrue(IsEqual(method, "DELETE"))) {
			if IsTrue(IsTrue((!IsEqual(queryLength, nil))) && IsTrue((!IsEqual(queryLength, 0)))) {
				url = Add(url, Add("?", this.Urlencode(query)))
			}
		} else {
			body = JsonStringify(params)
			headers = map[string]any{
				"Referrer":     "ccxt",
				"Content-Type": "application/json",
			}
		}
	} else {
		this.CheckRequiredCredentials()
		var isSpot bool = IsEqual(marketType, "spot")
		AddElementToObject(params, "timestamp", timestamp)
		if IsTrue(IsTrue(IsEqual(method, "GET")) || IsTrue((IsTrue(IsEqual(method, "DELETE")) && IsTrue(isSpot)))) {
			// For GET/DELETE: Append params to URL and sign the query string
			var queryString string = this.Urlencode(params)
			signature = this.Hmac(this.Encode(queryString), this.Encode(this.Secret), sha256, "hex")
			url = Add(url, Add("?", queryString))
		} else {
			// For POST/PUT: Convert body to JSON and sign the stringified payload
			body = this.Json(params)
			signature = this.Hmac(this.Encode(body), this.Encode(this.Secret), sha256, "hex")
		}
		headers = map[string]any{
			"Referrer":         "ccxt",
			"X-AUTH-APIKEY":    this.ApiKey,
			"X-AUTH-SIGNATURE": signature,
		}
		AddElementToObject(headers, "Content-Type", "application/json")
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
func (this *Zebpay) HandleErrors(code any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsTrue(IsEqual(response, nil)) {
		this.ThrowBroadlyMatchedException(GetValue(this.Exceptions, "broad"), body, body)
		return nil
	}
	//
	// bad
	//     { "code": "400100", "msg": "validation.createOrder.clientOidIsRequired" }
	// good
	//     { code: "200000", data: { ... }}
	// {"statusDescription":"Order quantity is out of range","data":{},"statusCode":400,"customMessage":["Order quantity is out of range"]}
	//
	var errorCode any = this.SafeString2(response, "code", "statusCode")
	var message any = this.SafeString2(response, "msg", "statusDescription")
	var feedback any = Add(Add(this.Id, " "), message)
	this.ThrowBroadlyMatchedException(GetValue(this.Exceptions, "broad"), message, feedback)
	this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), message, feedback)
	this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), errorCode, feedback)
	return nil
}

func NewZebpay(userConfig map[string]any) *Zebpay {
	p := newZebpay()
	p.Init(userConfig)
	return p
}

func (this *Zebpay) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

